style:
/* 잡지 (editorial) — 오래 가는. 큰 명조 제목 · 가는 가로줄 구분 · 작은 대문자풍 라벨 · 카드 대신 지면 */
.app{background:var(--bg)}
.app .body{gap:22px}
.app .h1{font-size:36px!important;font-weight:600;line-height:1.12;letter-spacing:-.02em}
.app .h1+.muted,.app .row .muted{font-size:.8em;letter-spacing:.14em;text-transform:uppercase}
.app .sec{border-top:1px solid var(--ink);padding-top:10px;margin-top:10px}
.app .sec b{font-weight:600;font-size:1.25em;font-style:italic}
.app .sec .muted{letter-spacing:.12em;font-size:.72em;text-transform:uppercase}
.app .card{background:transparent;border:0;border-radius:0;padding:0;box-shadow:none}
.app .stats{border-top:1px solid var(--ink);border-bottom:1px solid var(--line);padding:12px 0;gap:0}
.app .stat{padding:0 12px;border-left:1px solid var(--line)} .app .stat:first-child{border-left:0;padding-left:0}
.app .stat b{font-size:2.6em;font-weight:400;font-style:italic}
.app .stat span{letter-spacing:.12em;font-size:.7em;text-transform:uppercase}
.app .li{border-bottom:1px solid var(--line);padding:14px 0} .app .li b{font-weight:600;font-size:1.05em}
.app .dot{background:transparent;border:1px solid var(--ink);color:var(--ink);width:26px;height:26px}
.app .badge{background:transparent!important;border:1px solid currentColor;border-radius:0;font-weight:600;letter-spacing:.08em;font-size:.66em;text-transform:uppercase;padding:2px 6px}
.app .btn{border-radius:0;border:1px solid var(--ink);background:transparent;font-weight:600;letter-spacing:.04em}
.app .btn.p{background:var(--ink);color:var(--bg)}
.app .banner{border-radius:0;border-left:3px solid var(--accent);background:transparent!important;color:var(--ink)!important;font-style:italic;padding:4px 0 4px 14px}
.app .hero{border-radius:0;min-height:260px} .app .hero .cap b{font-size:1.8em;font-weight:500}
.app .cardi img{height:200px;filter:saturate(.85) contrast(1.05)} .app .cardi .in{padding:10px 0}
.app .tile{border-top:1px solid var(--ink);padding:12px 0}
.app .chip{border-radius:0;border:0;border-bottom:1px solid var(--line);background:transparent;padding:4px 2px} .app .chip.a{background:transparent;color:var(--ink);border-bottom:2px solid var(--ink)}
.app .seg{background:transparent;border-bottom:1px solid var(--line);border-radius:0} .app .seg span.a{box-shadow:none;background:transparent;border-bottom:2px solid var(--ink);border-radius:0}
.app .tl:before{border-left:1px solid var(--ink)} .app .tli:before{width:9px;height:9px;left:-20px;background:var(--ink)}
.app .quote{border-radius:0;background:transparent;border-left:1px solid var(--ink);font-style:italic;font-size:1.1em}
.app .tabbar{border-top:1px solid var(--ink);background:var(--bg)} .app .tabbar a{letter-spacing:.06em}
.app .side-nav{background:var(--bg);border-right:1px solid var(--ink)} .app .side-nav .brand{font-style:italic;font-weight:600;font-size:1.4em} .app .side-nav a.a{background:transparent;color:var(--ink);text-decoration:underline;text-underline-offset:5px}
.app .fld .in{border:0;border-bottom:1px solid var(--ink);border-radius:0;background:transparent;padding:10px 0}
.app .bign b{font-weight:400;font-style:italic;color:var(--ink);font-size:4.4em}
.app .poster h2{font-weight:500;font-size:2.4em}
@container (min-width:900px){ .app .h1{font-size:52px!important} .app .body{gap:28px} }
/* 여러 색 · 도형: 가는 아치 선과 색 점 */
.app .sec b:after{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--a2);margin-left:8px;vertical-align:.2em}

.app .body{position:relative} .app .body>*{position:relative;z-index:1}
.app .body:before{content:"";position:absolute;right:-10px;top:4px;width:120px;height:120px;background:var(--a2);opacity:.5;-webkit-mask:var(--m-arc) center/contain no-repeat;mask:var(--m-arc) center/contain no-repeat;z-index:0}
.app .badge.b-ok{color:var(--a3)!important} .app .badge.b-info{color:var(--a2)!important} .app .badge.b-warn{color:var(--a4)!important}


/* ===== 소식길 — 여행 소식지 (종이 · 이중선 제호 · 도장 vs 점선) ===== */
.app{--hf:"Noto Serif KR","Pretendard Variable",serif;--paper2:color-mix(in srgb,var(--ink) 6%,var(--bg))}
.app .body:before{display:none}
/* 부모(viewer)는 글자 125% — 버튼·목록·배지까지 같이 커진다 */
.app .scr[data-role="viewer"]{font-size:1.25em}
.app .scr[data-role="viewer"] .btn{min-height:58px;font-size:1.05em}
/* 제호(masthead): 이중선 + 호수 라벨 */
.app .mast{border-top:4px double var(--ink);border-bottom:1px solid var(--ink);padding:12px 0 14px;position:relative}
.app .mast:before{content:"소식길 · 제3호 준비중";display:block;font-size:.7em;letter-spacing:.2em;color:var(--muted);margin-bottom:6px}
.app .mast .h1{font-size:34px!important;font-weight:600}
/* 큰 숫자 */
.app .folio{border-top:1px solid var(--ink);padding-top:8px}
.app .folio .bign b{font-family:var(--hf);font-style:italic;font-weight:400;font-size:5em;line-height:1;color:var(--accent)}
/* 소식 약속 쪽지: 절취선 + 양옆 홈 */
.app .slip{border:1px dashed var(--ink)!important;border-left:1px dashed var(--ink)!important;border-radius:0!important;padding:14px 18px!important;font-style:normal!important;background:var(--paper2)!important;position:relative;
 -webkit-mask:radial-gradient(circle 9px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 9px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat;mask:radial-gradient(circle 9px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 9px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat}
/* 확정 = 도장, 후보/정하는 중 = 점선 기울임 */
.app .badge{border-radius:0}
.app .badge.b-ok,.app .li.st-done .badge,.app .tli:not(.draft) .badge{color:var(--accent)!important;border:2px solid var(--accent)!important;font-family:var(--hf);font-weight:800;letter-spacing:.24em;transform:rotate(-3deg);padding:1px 7px 1px 10px;background:transparent!important}
.app .li.st-draft .badge,.app .tli.draft .badge,.app .badge.b-muted{color:var(--a2)!important;border:1px dashed var(--a2)!important;font-style:italic;letter-spacing:.04em;text-transform:none;font-weight:600}
.app .st-draft .ttl,.app .st-draft b,.app .tli.draft .ttl{font-style:italic}
.app .tli.draft{opacity:1} .app .tli.draft .ttl{color:var(--ink)}
.app .tli.draft:before{background:var(--bg);border:1.5px dashed var(--a2);width:11px;height:11px}
.app .tli:before{background:var(--accent);width:11px;height:11px}
.app .tl:before{border-left:1px solid var(--ink)} .app .tl:has(.tli.draft):before{border-left-style:solid}
.app .st-done .dot{background:var(--accent);border-color:var(--accent);color:var(--bg)}
.app .st-draft .dot{border:1px dashed var(--a2);color:var(--a2);background:transparent}
.app .st-alert .dot{border-color:var(--a3);color:var(--a3)}
/* 조각 ① 사진·카드 대신 얇은 선 표 */
.app .tbl th{font-size:.72em;letter-spacing:.14em;text-transform:uppercase;border-bottom:1px solid var(--ink)}
.app .kan .kcol{background:transparent;border-top:2px solid var(--ink);border-radius:0;padding:10px 0 0}
.app .kan .kcol>b{font-family:var(--hf);font-size:1.1em}
.app .poster{border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);border-radius:0}
.app .steps span.a{background:var(--ink)!important;color:var(--bg)!important}
.app .banner.tone-warn,.app .banner:not(.slip){border-left:3px solid var(--a2)}
/* 폰 내비 pill: 라벨을 항상 보이게(부모가 아이콘만 보면 헷갈림) */
.app .m-pill .tabbar{border:1px solid var(--ink);border-radius:999px;background:var(--bg);box-shadow:0 3px 0 var(--ink);bottom:12px;padding:4px 6px;max-width:calc(100% - 20px)}
.app .m-pill .tabbar a{flex-direction:column;gap:1px;padding:6px 9px;border-radius:999px;min-width:0;color:var(--ink)}
.app .m-pill .tabbar a span{display:inline!important;font-size:12px;letter-spacing:0;white-space:nowrap}
.app .m-pill .tabbar a.a{background:var(--ink);color:var(--bg)}
.app .d-rail .side-nav{border-right:1px solid var(--ink)} .app .d-rail .side-nav a.a{background:var(--ink);color:var(--bg);text-decoration:none}

/* ===== 손으로 그린 화면(p-home · v-home · m-home) ===== */
.ed{display:flex;flex-direction:column;gap:22px}
.ed-mast{border-top:4px double var(--ink);border-bottom:1px solid var(--ink);padding:10px 0 16px}
.ed-kick{display:flex;justify-content:space-between;gap:12px;font-size:.7em;letter-spacing:.2em;color:var(--muted)}
.ed-h{word-break:keep-all;font-family:var(--hf);font-weight:600;font-size:34px;line-height:1.16;letter-spacing:-.02em;margin:10px 0 6px}
.ed-h em{font-style:italic;background:none;border-bottom:3px dashed var(--a2);padding:0 2px}
.ed-h em.ok{border-bottom:3px solid var(--accent);color:var(--accent)}
.ed-sub{word-break:keep-all;color:var(--muted);max-width:34em}
.ed-lab{font-size:.7em;letter-spacing:.18em;color:var(--muted);border-top:1px solid var(--ink);padding-top:8px;display:flex;justify-content:space-between;align-items:baseline}
.ed-lab b{font-family:var(--hf);font-style:italic;font-weight:600;font-size:1.5em;letter-spacing:0;color:var(--ink)}
.ed-map{position:relative}
.ed-map svg{width:100%;height:auto;display:block}
.ed-map .mp-land{fill:var(--paper2);stroke:var(--ink);stroke-width:.35;stroke-linejoin:round}
.ed-map .mp-leg{fill:none;stroke:var(--a2);stroke-width:.7;stroke-dasharray:1.6 1.4;stroke-linecap:round}
.ed-map .mp-leg.fx{stroke:var(--accent);stroke-dasharray:none;stroke-width:1.1}
.ed-map .mp-pin{fill:var(--accent);stroke:var(--bg);stroke-width:.5} .ed-map .mp-pin.dr{fill:var(--bg);stroke:var(--a2);stroke-width:.7;stroke-dasharray:1 .8}
.ed-map .mp-num{font:700 3px "Noto Serif KR",serif;fill:var(--bg);text-anchor:middle} .ed-map .mp-num.dr{fill:var(--a2)}
.ed-map .mp-lab{font:700 3.6px "Noto Serif KR",serif;fill:var(--ink)} .ed-map .mp-lab.dr{font-style:italic;fill:var(--a2)} .ed-map .mp-tiny{font:500 2.6px "Pretendard Variable",sans-serif;fill:var(--muted);letter-spacing:.1px} .ed-map .mp-sea{font:italic 500 2.8px "Noto Serif KR",serif;fill:var(--a2);opacity:.8}
.ed-key{display:flex;gap:18px;flex-wrap:wrap;font-size:.78em;color:var(--muted);margin-top:6px}
.ed-key i{display:inline-block;width:26px;border-top:3px solid var(--accent);vertical-align:.3em;margin-right:6px} .ed-key i.d{border-top:2px dashed var(--a2)}
.days{display:flex;gap:0;overflow-x:auto;scroll-snap-type:x mandatory;border-top:2px solid var(--ink)}
.dy{flex:0 0 46%;scroll-snap-align:start;padding:10px 12px 12px 0;margin-right:12px;border-right:1px solid var(--line);display:block}
.dy .n{font-family:var(--hf);font-style:italic;font-size:2.6em;line-height:1;color:var(--ink)}
.dy .d{font-size:.78em;color:var(--muted);margin-top:2px} .dy .p{font-weight:700;margin:6px 0}
.stp{display:inline-block;width:11px;height:11px;margin-right:4px;background:var(--accent)} .stp.o{background:transparent;border:1.5px dashed var(--a2)}
.dy .c{font-size:.72em;color:var(--muted);margin-top:4px}
.dy.hot{background:var(--paper2)}
.ed-pn{display:flex;flex-direction:column;gap:20px}
.pv{border-top:2px solid var(--ink);background:var(--paper2);padding:12px 14px}
.pv h4{font-family:var(--hf);font-size:1.15em;margin:0 0 8px}
.pvr{display:flex;gap:10px;align-items:baseline;padding:7px 0;border-bottom:1px solid var(--line)} .pvr:last-child{border:0}
.pvr time{font-variant-numeric:tabular-nums;font-size:.82em;color:var(--muted);flex:none;width:3.4em}
.pvr.t{font-style:italic;color:var(--a2)} .pvr.t:after{content:"";}
.seal{display:inline-block;color:var(--accent);border:2px solid var(--accent);font-family:var(--hf);font-weight:800;letter-spacing:.24em;font-size:.72em;padding:0 6px 0 9px;transform:rotate(-3deg);flex:none}
.tent{display:inline-block;color:var(--a2);border:1px dashed var(--a2);font-style:italic;font-size:.72em;padding:0 7px;flex:none}
.pvr .seal,.pvr .tent{margin-left:auto}
.q{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line);align-items:baseline} .q:last-child{border:0} .q small{color:var(--muted);display:block;font-size:.76em}
.ed-btns{display:flex;gap:10px;flex-wrap:wrap} .ed-btns a{flex:1;min-width:8em;min-height:52px;display:flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--ink);font-weight:700;letter-spacing:.03em;padding:0 14px;text-align:center}
.ed-btns a.p{background:var(--ink);color:var(--bg)}
.ed-slip{padding:16px 22px;border:1px dashed var(--ink);background:var(--paper2);-webkit-mask:radial-gradient(circle 9px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 9px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat;mask:radial-gradient(circle 9px at 0 50%,#0000 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 9px at 100% 50%,#0000 98%,#000) right/51% 100% no-repeat}
.ed-slip small{display:block;font-size:.7em;letter-spacing:.2em;color:var(--muted)} .ed-slip b{font-family:var(--hf);font-size:1.7em;font-weight:600;line-height:1.25;display:block;margin:2px 0}
.ed-slip span{font-size:.86em;color:var(--muted)}
.row5{display:grid;gap:0}
.day5{display:grid;grid-template-columns:2.6em 1fr auto;gap:12px;align-items:center;padding:16px 0;border-bottom:1px solid var(--line)}
.day5 .n{font-family:var(--hf);font-style:italic;font-size:2.4em;line-height:1}
.day5 b{display:block;font-size:1.05em} .day5 small{display:block;color:var(--muted);font-size:.8em;margin-top:2px}
.day5.t b,.day5.t small{font-style:italic}
.mine{display:grid;grid-template-columns:auto 1fr;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);align-items:baseline}
.mine time{font-variant-numeric:tabular-nums;font-weight:700;min-width:5.6em} .mine small{display:block;color:var(--muted);font-size:.8em}
.todo{display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--line);align-items:flex-start}
.ck{width:18px;height:18px;border:1.5px solid var(--ink);flex:none;margin-top:3px;display:grid;place-items:center;font-size:12px;line-height:1} .ck.on{background:var(--accent);border-color:var(--accent);color:var(--bg)}
.todo small{display:block;color:var(--muted);font-size:.8em}
.bigd{display:flex;align-items:flex-end;gap:14px;border-top:2px solid var(--ink);padding-top:12px}
.bigd .n{white-space:nowrap;font-family:var(--hf);font-style:italic;font-size:4.4em;line-height:.9;color:var(--accent)} .bigd b{display:block;font-size:1.1em} .bigd small{color:var(--muted)}
@container (min-width:900px){
 .ed-h{font-size:56px}
 .ed-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:40px;align-items:start}
 .days{border-top:2px solid var(--ink)} .dy{flex:1 1 0;margin-right:14px}
 .ed-grid.two{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
 .ed-grid.v{grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr)}
 .app .mast .h1{font-size:52px!important}
}
.day5 b,.day5 small,.q span,.todo span,.mine span{word-break:keep-all}

/* 일반 화면 제목: 한글은 자간을 벌리지 않는다 */
.app .h1{word-break:keep-all;font-size:30px!important}
.app .h1+.muted,.app .row .muted{letter-spacing:.01em!important;text-transform:none!important;font-size:.9em!important}
.app .btns .btn{flex:1 1 9em;min-width:0;padding:0 10px;text-align:center}
.app .st-done .dot{background:var(--accent)!important;border-color:var(--accent)!important;color:var(--bg)!important}
@container (min-width:900px){ .app .h1{font-size:44px!important} .app .mast .h1{font-size:52px!important} }

.app .banner{font-style:normal!important}
.app .slip .banner{border:0!important;padding:0!important;background:transparent!important;color:var(--ink)!important}
.app .tbl table{min-width:0!important} .app .tbl td,.app .tbl th{word-break:keep-all}

/* PC: 가운데 정렬(center)이어도 보조 열이 있으면 본문+보조 두 열 — 폰을 넓힌 모양 금지 */
@container (min-width:900px){
 .app .scr.on.l-center:not(.nos){max-width:1240px;display:grid;grid-template-columns:minmax(0,1.6fr) minmax(320px,1fr);align-items:start}
 .app .scr.on.l-center:not(.nos) .aside{margin-top:0;padding:20px 36px 48px 28px;border-left:1px solid var(--line);min-height:70vh}
 .app .aside .btns .btn{flex:1 1 100%}
}

/* ---- 비평 반영 ---- */
.ed-map text{paint-order:stroke;stroke:var(--paper2);stroke-width:1px;stroke-linejoin:round}
.ed-map .mp-num{stroke:none}
@container (max-width:600px){.ed-map .mp-lab{font-size:4.8px}.ed-map .mp-tiny{font-size:3.8px}.ed-map .mp-sea{font-size:4px}}
.ed-btns a:nth-child(2){border:2px solid var(--accent);color:var(--accent);font-family:var(--hf);letter-spacing:.2em;transform:rotate(-1.2deg)}
.ed-btns a:nth-child(4){flex:0 0 auto;border:0;text-decoration:underline;text-underline-offset:5px;min-width:0}
.pubseg .seg span:first-child.a{border:1px dashed var(--a2)!important;color:var(--a2);font-style:italic}
.pubseg .seg span:last-child.a{border:2px solid var(--accent)!important;color:var(--accent);font-family:var(--hf);letter-spacing:.24em;transform:rotate(-2deg)}
.app .badge{font-size:max(12px,.74em)!important} .seal,.tent{font-size:max(13px,.72em)}
.app .tli.draft:before{width:14px;height:14px;left:-23px;border-width:2px}
.app .tli:before{width:12px;height:12px;left:-22px}
.ck{width:26px;height:26px;font-size:16px;margin-top:0}
.app .m-pill .tabbar a{min-height:52px;padding:8px 9px;justify-content:center}
.app .m-pill .tabbar a span{font-size:13px!important}
@container (min-width:900px){
 .app .d-rail .side-nav a{font-family:var(--hf);font-size:14px;min-height:48px;justify-content:center;padding:10px 2px;border-radius:0}
 .app .d-rail .side-nav a svg{display:none}
 .app .d-rail .side-nav a.a{background:transparent;color:var(--ink);border-bottom:3px double var(--ink);font-weight:700}
}
